146: 
147:             {activeTab === 'evaluation' && (
148:               <ModelEvaluation stats={stats} />
149:             )}
150: 
151:             {activeTab === 'feedback' && (
152:               <FeedbackHistory onSelectTransaction={handleSelectTransaction} />
